/* Frontend only. All authored content is escaped; all local decisions are scoped to company and event version. */
(function () {
  'use strict';
  const M=window.PulseModel, e=M.escape, arr=M.array;
  const $=selector=>document.querySelector(selector);
  const paths={
    grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
    pulse:'M3 12h4l3-7 4 14 3-7h4', bookmark:'M6 3h12v18l-6-4-6 4z',
    check:'M5 12l4 4L19 6', tasks:'M9 6h12 M9 12h12 M9 18h12 M3 6h1 M3 12h1 M3 18h1',
    building:'M4 21V5h10v16 M14 10h6v11 M8 9h2 M8 13h2 M8 17h2 M2 21h20',
    arrow:'M4 12h16 M14 6l6 6-6 6', back:'M20 12H4 M10 6l-6 6 6 6',
    refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-2l2 7 M4 12l2 7a7 7 0 0 0 12-2',
    search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15 M16 16l5 5',
    info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7v1',
    spark:'M12 3l2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3z',
    doc:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',
    external:'M14 3h7v7 M21 3l-11 11 M10 3H3v18h18v-7',
    clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',
    shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',
    alert:'M12 3L2 21h20z M12 9v5 M12 17v1',
    trend:'M3 17l6-6 4 4 8-10 M15 5h6v6',
    link:'M10 14l4-4 M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0 M14 8l2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',
    message:'M21 4H3v14h5l4 4v-4h9z M7 9h10 M7 13h6',
    download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5'
  };
  const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.info).split(' M').map((p,i)=>`<path d="${i?'M':''}${p}"/>`).join('')}</svg>`;
  let storageAvailable=true, stored={};
  try {stored=JSON.parse(localStorage.getItem('pulse:v3')||'{}')||{};} catch {storageAvailable=false;}
  const state={data:null,status:'loading',companyId:typeof stored.companyId==='string'?stored.companyId:'company_demo_001',role:Object.hasOwn(M.roles,stored.role)?stored.role:'financial_director',
    bookmarks:stored.bookmarks && typeof stored.bookmarks==='object'?stored.bookmarks:{},read:arr(stored.read),done:arr(stored.done),feedback:stored.feedback && typeof stored.feedback==='object'?stored.feedback:{},
    query:'',category:'all',priority:'all',period:'all',sort:'relevance',scenario:new URLSearchParams(location.search).get('state')||'ready',error:'',request:0};
  const priorityLabels={high:'Высокий приоритет',medium:'Средний приоритет',low:'Наблюдение'};
  const tabLabels={analysis:'Разбор',risks:'Риски и возможности',actions:'План действий',sources:'Источники и проверка'};
  let toastTimeout, answerRequest=0, fetchController=null;
  const questionSessions=new Map();
  const questionKey=event=>`${M.stateKey(state.companyId,event)}:${state.role}`;
  function captureQuestion(){const form=$('#question-form'),input=$('#question-input');if(form&&input){const key=form.dataset.context,session=questionSessions.get(key)||{};session.draft=input.value;questionSessions.set(key,session);}}
  function restoreQuestion(){const form=$('#question-form');if(!form)return;const session=questionSessions.get(form.dataset.context);if(!session)return;const answer=$('#question-answer'),input=$('#question-input');input.value=session.draft||'';answer.hidden=!session.html&&!session.pending;answer.className=`question-answer${session.error?' error':''}`;answer.innerHTML=session.pending?'Ожидаем ответ…':session.html||'';$('#question-form button').disabled=!!session.pending;}
  function persist(){try{localStorage.setItem('pulse:v3',JSON.stringify({companyId:state.companyId,role:state.role,bookmarks:state.bookmarks,read:state.read,done:state.done,feedback:state.feedback}));}catch{storageAvailable=false;}}
  function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
  const company=()=>state.data?.companies.find(c=>c.id===state.companyId);
  const events=()=>state.data?M.getEvents(state.data,{companyId:state.companyId,role:state.role}):[];
  const saved=()=>arr(state.bookmarks[state.companyId]);
  const read=event=>state.read.includes(M.stateKey(state.companyId,event));
  const doneKey=(event,action)=>`${M.stateKey(state.companyId,event)}:${action.id}`;
  const isDone=(event,action)=>state.done.includes(doneKey(event,action));
  function route(){const parts=location.hash.slice(1).split('/');return {view:parts[0]||'overview',id:parts[1]||'',tab:tabLabels[parts[2]]?parts[2]:'analysis'};}
  const dateLabel=date=>{try{return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(date.slice(0,10)+'T12:00:00Z')).replace('.','');}catch{return 'Дата не указана';}};
  const eventUrl=(event,tab='analysis')=>`#insight/${encodeURIComponent(event.id)}/${tab}`;
  const priority=event=>`<span class="pill ${e(event.priority)}">${event.priority==='high'?'<span class="status-dot" style="background:currentColor"></span>':''}${priorityLabels[event.priority]}</span>`;
  function featureRefs(event){const c=company();return arr(event.relevance[state.companyId]?.feature_refs).map(ref=>c?.features.find(f=>f.field===ref)).filter(Boolean);}
  function demoStrip(){return state.data?.is_demo?`<div class="demo-strip">${icon('info',16)}<span>Демонстрационные новости и компании. Разборы и ответы подготовлены заранее. <button data-action="about">Подробнее о демо</button></span></div>`:'';}
  function navigation(){const r=route(), active=r.view==='insight'?'feed':r.view; const count=events().filter(n=>!read(n)).length;$('#navigation').innerHTML=[['overview','grid','Обзор компании'],['feed','pulse','Бизнес-пульс',count],['saved','bookmark','Сохранённое',saved().length],['actions','tasks','План действий'],['company','building','Профиль компании']].map(([key,ico,label,n],index)=>`${index===4?'<div class="nav-divider" aria-hidden="true"></div>':''}<a href="#${key}" ${active===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${n?`<span class="count" aria-label="${n} событий">${n}</span>`:''}</a>`).join('');}
  function updateChrome(){const demo=state.data?.is_demo!==false;const badge=document.querySelector('.demo-badge');if(badge)badge.hidden=!demo;const stamp=document.querySelector('.demo-stamp');if(stamp)stamp.innerHTML=demo?'<span></span> Пространство демо':'<span></span> Рабочее пространство';const note=document.querySelector('.sidebar-bottom p');if(note)note.innerHTML=demo?'Вымышленные компании.<br>Реальные возможности интерфейса.':'События подобраны по профилю<br>выбранной компании.';const about=document.querySelector('.sidebar-bottom .text-button');if(about)about.hidden=!demo;const footer=document.querySelector('.workspace footer');if(footer)footer.textContent=demo?'Учебный прототип · Вымышленные данные · Не является действующим сервисом Альфа-Банка':'Прототип Бизнес-пульса · Не является обещанием банка или инвестиционной рекомендацией';const who=document.querySelector('.user-profile div');if(who)who.innerHTML=demo?'Демо-пользователь<small>Рабочее пространство</small>':'Руководитель<small>Рабочее пространство</small>';}
  function updateHeader(){if(!state.data)return;$('#company-select').innerHTML=state.data.companies.map(c=>`<option value="${e(c.id)}" ${c.id===state.companyId?'selected':''}>${e(c.short_name||c.display_name)}</option>`).join('');$('#company-select').disabled=!state.data.companies.length;$('#role-select').value=state.role;}
  async function jsonRequest(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),window.ALFA_CONFIG.requestTimeoutMs||10000);if(!options.question)fetchController=controller;
    try{const response=await fetch(url,{...options,signal:controller.signal,headers:{Accept:'application/json',...(options.body?{'Content-Type':'application/json'}:{})}});if(!response.ok)throw new Error(`Сервер вернул ошибку ${response.status}.`);return await response.json();}catch(error){if(error.name==='AbortError')throw new Error('Время ожидания истекло. Попробуйте ещё раз.');throw error;}finally{clearTimeout(timer);}}
  async function load(){const request=++state.request;answerRequest++;fetchController?.abort();state.status='loading';render();
    try{await new Promise(resolve=>setTimeout(resolve,350));if(request!==state.request)return;if(state.scenario==='loading')return;if(state.scenario==='error')throw new Error('Учебный сценарий: источник данных временно недоступен.');
      let data;
      const base=String(window.ALFA_CONFIG.apiBaseUrl||'').replace(/\/$/,'');
      if(base)data=await jsonRequest(`${base}/workspace?company_id=${encodeURIComponent(state.companyId)}&role=${encodeURIComponent(state.role)}`);
      else if(location.protocol==='file:')data=structuredClone(window.ALFA_DEMO);
      else data=await jsonRequest('data/demo.json');
      if(request!==state.request)return;
      data=M.validateDataset(data);
      if(state.scenario==='empty')data.events=[];
      if(state.scenario==='partial' && data.events[0]){const n=data.events[0];n.facts=[];n.sources=[];n.ai_interpretation={assumptions:[],risks:[],opportunities:[],reasoning_steps:[]};Object.values(n.relevance).forEach(r=>{r.summary='';r.role_summary={};});n.actions=[];n.suggested_questions=[];n.missing_data=['Текст первоисточника','Проверенные факты','Материалы банка','Подготовленная интерпретация'];}
      state.data=data;if(!company())state.companyId=data.companies[0]?.id||'';state.status='ready';state.error='';persist();updateHeader();render();
    }catch(error){if(request!==state.request)return;state.status='error';state.error=error instanceof SyntaxError?'Не удалось прочитать ответ: ожидается корректный JSON.':error.message||'Источник данных недоступен.';render();}}
  function pageHead(title,description,eyebrow='ВАШЕ РАБОЧЕЕ ПРОСТРАНСТВО'){return `<div class="page-head"><div><div class="eyebrow">${e(eyebrow)}</div><h1>${e(title)}</h1><p>${e(description)}</p></div><button class="button secondary" data-action="reload" aria-label="Обновить данные">${icon('refresh',16)} Обновить</button></div>`;}
  function render(focus=false){captureQuestion();navigation();const main=$('#main');main.setAttribute('aria-busy',String(state.status==='loading'));const r=route();
    if(state.status==='loading'){main.innerHTML=`<div role="status" aria-live="polite"><p class="muted small">Загружаем события и контекст компании…</p><div class="skeleton title"></div><div class="loading-wrap"><div>${Array.from({length:3},()=>'<div class="skeleton block"></div>').join('')}</div><div class="skeleton block"></div></div></div>${state.scenario==='loading'?'<button class="button secondary" data-action="restore">Завершить демонстрацию загрузки</button>':''}`;return;}
    if(state.status==='error'){main.innerHTML=pageHead('Не удалось загрузить аналитику','Ваши сохранённые события и отметки остаются в этом браузере.')+empty('Источник данных недоступен',state.error,'refresh','Повторить запрос','reload',true)+`<p class="local-note" style="margin-top:16px">${window.ALFA_CONFIG.apiBaseUrl?'Данные сервера не подменяются демо. Проверьте доступность API.':'Это локальное демо. Можно повторить загрузку или восстановить исходный набор.'}</p><button class="text-button" data-action="about">Параметры демо</button>`;return;}
    if(!company()){main.innerHTML=empty('Компании не найдены','Для персональной аналитики нужен доступный профиль компании.','building','Обновить','reload');return;}
    if(r.view==='overview')main.innerHTML=overview();
    else if(r.view==='feed'||r.view==='saved')main.innerHTML=feed(r.view);
    else if(r.view==='company')main.innerHTML=profile();
    else if(r.view==='actions')main.innerHTML=actionsPage();
    else if(r.view==='insight')main.innerHTML=detail(r);
    else main.innerHTML=empty('Страница не найдена','Вернитесь к событиям выбранной компании.','search','Открыть Бизнес-пульс','go-feed');
    updateChrome();restoreQuestion();
    if(focus){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
  }
  function empty(title,text,ico='search',label='Сбросить фильтры',action='reset-filters',error=false){return `<section class="empty-state ${error?'error-state':''}" role="${error?'alert':'status'}"><div class="empty-icon">${icon(ico,25)}</div><h2>${e(title)}</h2><p>${e(text)}</p>${label?`<button class="button ${error?'primary':'secondary'}" data-action="${action}">${e(label)}</button>`:''}</section>`;}
  function contextRail(){const c=company(),features=c.features.slice(0,4);return `<aside class="rail"><section class="card"><div class="eyebrow">КОНТЕКСТ АНАЛИТИКИ</div><div class="row" style="margin-bottom:14px"><span class="company-symbol">${icon('building',22)}</span><div><div class="company-name">${e(c.short_name||c.display_name)}</div><span class="muted small">${e(c.industry||'Отрасль не указана')}</span></div></div>${features.map(f=>`<div class="feature-row"><span>${e(f.label)}</span><strong>${e(M.featureText(f))}</strong></div>`).join('')}<hr><a class="link" href="#company">Профиль и полнота данных ${icon('arrow',14)}</a></section><section class="card bank-rail"><div class="bank-logo"><span>А</span> Взгляд Альфа-Банка</div><p style="margin-top:14px">${(state.data?.events||[]).some(ev=>(ev.company_ids||[]).includes(state.companyId)&&ev.bank_view?.status==='available')?'По событию компании найден фрагмент аналитики банка. Он показан в разборе отдельно от новости.':'Материалы банка не подключены. Его позиция не представлена и не используется в демо-разборах.'}</p><span class="pill outline">${icon('doc',13)} ${(state.data?.events||[]).some(ev=>(ev.company_ids||[]).includes(state.companyId)&&ev.bank_view?.status==='available')?'Материал есть в разборе':'Ожидаем материалы'}</span></section><div class="rail-note">${icon('shield',18)}<span>Каждый вывод связан с исходными данными. Неизвестные условия обозначены явно.</span></div></aside>`;}
  function metric(value,label,description,red=false,ico='pulse'){return `<div class="card metric"><div class="metric-value ${red?'red':''}">${value}</div><div><strong>${e(label)}</strong><small>${e(description)}</small></div><div class="metric-icon">${icon(ico,21)}</div></div>`;}
  function overview(){const list=events(),urgent=list.filter(n=>n.priority==='high').length,pending=list.flatMap(n=>n.actions.filter(a=>!isDone(n,a))).length;return pageHead('Ваш бизнес. В контексте.','События, которые стоит учесть в решениях вашей компании.','ОБЗОР КОМПАНИИ')+demoStrip()+`<div class="layout"><div><section class="overview-hero"><div class="hero-content"><div class="eyebrow">БИЗНЕС-ПУЛЬС</div><h2>От новостей —<br>к пониманию последствий.</h2><p>Что меняется для вашего бизнеса, на чём основан вывод и что стоит проверить дальше.</p><a class="button primary" href="#feed">Открыть Бизнес-пульс ${icon('arrow',16)}</a></div><div class="hero-art" aria-hidden="true"><div class="orb">${icon('pulse',80)}</div><span class="float-label">Контекст → событие → решение</span></div></section><div class="metrics">${metric(list.length,'События для вас',state.data?.is_demo?'В демонстрационной ленте':'В вашей ленте')}${metric(urgent,'Высокий приоритет','Стоит проверить',true,'alert')}${metric(pending,'Следующие шаги','В личном плане',false,'tasks')}</div><div class="section-heading"><h2>В фокусе сегодня</h2><a class="link" href="#feed">Все события ${icon('arrow',14)}</a></div><div class="feed-list">${list.slice(0,2).map(newsCard).join('')||empty('Пока нет событий','В этом наборе нет событий для выбранной компании.','pulse','Обновить','reload')}</div></div>${contextRail()}</div>`;}
  function newsCard(event){const isSaved=saved().includes(event.id);return `<article class="card news-card"><div class="card-meta"><div class="meta">${!read(event)?'<span class="new-dot" title="Не прочитано"></span>':''}<span>${e(event.category_label||event.category)}</span><span class="separator"></span><time datetime="${e(event.date)}">${dateLabel(event.date)}</time></div>${priority(event)}</div><h2><a href="${eventUrl(event)}">${e(event.title)}</a></h2><p class="summary">${e(event.summary||'Краткое описание ещё не подготовлено.')}</p><div class="impact-box"><div class="impact-title">${icon('spark',13)} ${state.data?.is_demo?'Демо-интерпретация · для вашей компании':'Для вашей компании'}</div><p>${e(M.impact(event,state.companyId,state.role))}</p>${featureRefs(event).length?`<div class="feature-chips">${featureRefs(event).slice(0,3).map(f=>`<span>${e(f.label)}</span>`).join('')}</div>`:''}</div><div class="card-bottom"><div class="row"><a class="link" href="${eventUrl(event)}">Разобрать влияние ${icon('arrow',14)}</a><button class="icon-button" data-action="bookmark" data-id="${e(event.id)}" aria-label="${isSaved?'Убрать из сохранённого':'Сохранить событие'}: ${e(event.title)}" aria-pressed="${isSaved}">${icon('bookmark',17)}</button></div><span class="source-caption">${icon('doc',13)} ${event.sources.length} ист. <span>·</span> ${read(event)?'Прочитано':'Нужны данные'}</span></div></article>`;}
  function feed(view){const isSaved=view==='saved',list=events(),categories=[...new Map(list.map(n=>[n.category,n.category_label])).entries()];return pageHead(isSaved?'Сохранённое':'Бизнес-пульс',isSaved?'Возвращайтесь к важным событиям и решениям.':'Значимые события. Влияние на вашу компанию. Обоснованные следующие шаги.',isSaved?'ВАША ПОДБОРКА':'ПЕРСОНАЛЬНАЯ АНАЛИТИКА')+demoStrip()+`<div class="layout"><section aria-label="Лента событий"><div class="feed-toolbar"><div class="search-line"><div class="search-wrap">${icon('search',17)}<input type="search" id="search" aria-label="Поиск по событиям" placeholder="Найти событие, тему или влияние…" value="${e(state.query)}"></div><select class="sort-select" id="sort-select" aria-label="Сортировка"><option value="relevance" ${state.sort==='relevance'?'selected':''}>По значимости</option><option value="date" ${state.sort==='date'?'selected':''}>Сначала новые</option></select></div><div class="filters"><select id="category-filter" aria-label="Тема"><option value="all">Все темы</option>${categories.map(([value,label])=>`<option value="${e(value)}" ${state.category===value?'selected':''}>${e(label||value)}</option>`).join('')}</select><select id="priority-filter" aria-label="Приоритет"><option value="all">Любой приоритет</option>${Object.entries(priorityLabels).map(([value,label])=>`<option value="${value}" ${state.priority===value?'selected':''}>${label}</option>`).join('')}</select><select id="period-filter" aria-label="Период"><option value="all">Весь период</option><option value="1" ${state.period==='1'?'selected':''}>За день</option><option value="7" ${state.period==='7'?'selected':''}>За неделю</option></select><button class="filter-reset" data-action="reset-filters">Сбросить</button></div></div><div class="feed-summary"><span>Для роли: <strong>${e(M.roles[state.role])}</strong></span><button data-action="ranking">Как отобраны события</button></div><div id="feed-results" aria-live="polite">${feedResults(isSaved)}</div></section>${contextRail()}</div>`;}
  function feedResults(isSaved){const list=M.getEvents(state.data,{companyId:state.companyId,role:state.role,query:state.query,category:state.category,priority:state.priority,period:state.period,sort:state.sort,bookmarked:isSaved?saved():undefined});return `<p class="small muted" style="margin-bottom:13px">Событий: ${list.length} <span aria-hidden="true">·</span> ${state.data?.is_demo?'Срез демо':'Срез'}: ${dateLabel(state.data.as_of||'2026-10-22')} ${e((state.data.as_of||'2026-10-22').slice(0,4))}</p><div class="feed-list">${list.map(newsCard).join('')|| (isSaved&&!saved().length?empty('Здесь будет важное','Сохраните событие с помощью значка закладки, чтобы вернуться к нему позже.','bookmark','Открыть события','go-feed'):empty('Подходящих событий нет','Попробуйте другую тему, период или поисковый запрос.','search'))}</div>`;}
  function profile(){const c=company();return pageHead('Контекст вашей компании','Показываем, какие данные участвуют в персонализации и чего пока не хватает.','ПРОФИЛЬ КОМПАНИИ')+demoStrip()+`<section class="card" style="margin-bottom:24px"><div class="row"><span class="company-symbol">${icon('building',24)}</span><div><h2 style="margin:0 0 6px">${e(c.display_name)}</h2><p class="muted small" style="margin:0">${e(c.description||c.industry||(state.data?.is_demo?'Синтетический профиль для демонстрации.':'Профиль из данных клиента'))}</p></div></div></section><div class="section-heading"><h2>Что учитывает Бизнес-пульс</h2><span class="muted">${state.data?.is_demo?'Синтетический профиль':'Признаки профиля'}</span></div><div class="profile-grid">${c.features.map(f=>`<section class="card profile-field"><div class="eyebrow">${e(f.label)}</div><strong>${e(M.featureText(f))}</strong><small>${e(typeof f.source==='string'?f.source:'Демонстрационные данные')}</small></section>`).join('')}</div><section class="card analysis-section" style="margin-top:22px"><div class="row">${icon('info',19)}<h2 style="margin:0">Полнота профиля</h2></div><p style="margin-top:16px">Нет данных — не значит «нет влияния». Эти сведения нужны для более точной оценки:</p><ul>${[...new Set([...c.missing_data,'Доля рынка и положение компании в отрасли не определены','Аналитические материалы Альфа-Банка не подключены'])].map(text=>`<li>${e(text)}</li>`).join('')}</ul><a class="button primary" href="#feed">Перейти к событиям ${icon('arrow',16)}</a></section>`;}
  function getEvent(id){return events().find(n=>n.id===decodeURIComponent(id));}
  function detail(r){let event;try{event=getEvent(r.id);}catch{}if(!event)return empty('Событие недоступно','Возможно, оно относится к другой компании или было удалено из текущего набора.','search','Вернуться в ленту','go-feed');if(!read(event)){state.read.push(M.stateKey(state.companyId,event));persist();navigation();}
    return `<a href="#feed" class="back-link">${icon('back',15)} К событиям компании</a>${demoStrip()}<div class="meta">${priority(event)}<span>${e(event.category_label)}</span><span class="separator"></span><time datetime="${e(event.date)}">${dateLabel(event.date)}</time><span class="separator"></span><span>${state.data?.is_demo?'Учебное событие':'Событие из ленты'}</span></div><h1 class="detail-title">${e(event.title)}</h1><p class="detail-intro">${e(event.summary)}</p><div class="detail-tools"><button class="button secondary" data-action="bookmark" data-id="${e(event.id)}" aria-pressed="${saved().includes(event.id)}">${icon('bookmark',15)} ${saved().includes(event.id)?'Сохранено':'Сохранить событие'}</button><a class="button secondary" href="${eventUrl(event,'actions')}">${icon('tasks',15)} Следующие шаги · ${event.actions.length}</a><span class="pill outline"><span class="status-dot"></span> ${event.analysis_status==='ready'?'Разбор готов':'Неполный анализ'}</span></div><div class="layout detail-grid"><div><div class="tabs" role="tablist" aria-label="Разделы события">${Object.entries(tabLabels).map(([key,label])=>`<button role="tab" id="tab-${key}" data-tab="${key}" aria-controls="insight-panel" aria-selected="${r.tab===key}" tabindex="${r.tab===key?0:-1}">${label}</button>`).join('')}</div><section id="insight-panel" role="tabpanel" aria-labelledby="tab-${r.tab}" tabindex="0">${r.tab==='analysis'?analysis(event):r.tab==='risks'?risks(event):r.tab==='actions'?actionPanel(event):sourcesPanel(event)}</section>${feedback(event)}</div><aside class="rail">${questions(event)}<div class="rail-note">${icon('shield',18)}<span>Факты, позиция банка и интерпретация разделены. ${state.data?.is_demo?'Демо-разбор не заменяет проверку исходных данных.':'Факты и позиция банка не подменяют друг друга.'}</span></div></aside></div>`;
  }
  function analysis(event){const ai=event.ai_interpretation;return `<section class="card analysis-section"><div class="section-label"><span><span class="section-number">01</span> Что произошло</span><span class="pill source">Сведения из источника</span></div>${event.facts.length?event.facts.map(f=>`<div class="fact"><p>${e(f.text)}</p>${f.has_source?`<button class="source-link" data-action="source" data-id="${e(event.id)}" data-source="${e(f.source_id)}">${icon('doc',13)} ${e(event.sources.find(s=>s.id===f.source_id)?.title||'Источник')} ${icon('external',12)}</button>`:'<span class="pill medium">Источник не загружен · факт не подтверждён</span>'}</div>`).join(''):'<p class="empty-inline" style="margin-top:16px">Проверенные факты пока не загружены. Вывод по событию делать рано.</p>'}<p class="small muted" style="font-size:10px;margin:15px 0 0">${state.data?.is_demo?'Демо: связь с учебным источником не означает подтверждение реального события.':'Цифры в фактах взяты из текста источника.'}</p></section>${bankPanel(event)}<section class="card analysis-section ai-section"><div class="section-label"><span><span class="section-number">03</span> Что это значит для вас</span><span class="pill ai">${icon('spark',12)} ${state.data?.is_demo?'Демо-разбор':'Интерпретация'}</span></div>${ai.summary?`<p class="impact-lead" style="margin-top:18px">${e(M.impact(event,state.companyId,state.role))}</p><div class="reason-box"><h3>ПОЧЕМУ ЭТО ВАЖНО ИМЕННО ВАМ</h3><p>${e(event.relevance[state.companyId]?.reason||'Обоснование релевантности не загружено.')}</p>${featureRefs(event).length?`<div class="feature-chips">${featureRefs(event).map(f=>`<span>${e(f.label)}: ${e(M.featureText(f))}</span>`).join('')}</div>`:''}</div><p class="small" style="font-size:11px">${state.data?.is_demo?'Подготовленный вручную пример AI-интерпретации. Модель не вызывалась; позиция банка не подменяется этим текстом.':'Разбор собрал сервер по профилю компании и источникам. Это не позиция банка, если фрагмент банка не показан отдельно.'}</p><details class="disclosure"><summary>Основания и допущения</summary><ol class="step-list">${ai.reasoning_steps.map(step=>`<li>${e(step)}</li>`).join('')}</ol>${ai.assumptions.length?`<h4>Что пока предполагается</h4><ul>${ai.assumptions.map(a=>`<li>${e(a)}</li>`).join('')}</ul>`:''}${basis(event,ai.basis)}</details>`:'<p class="empty-inline" style="margin-top:18px">Интерпретация не подготовлена. Недостаточно исходных данных; автоматический вывод не показан.</p>'}</section><section class="card analysis-section"><h2>Что проверить перед решением</h2>${event.missing_data.length?`<ul>${event.missing_data.map(item=>`<li>${e(item)}</li>`).join('')}</ul>`:'<p>Данные о полноте анализа не предоставлены.</p>'}<a class="link" href="${eventUrl(event,'actions')}">Посмотреть следующие шаги ${icon('arrow',15)}</a></section>`;}
  function bankPanel(event){const bank=event.bank_view;return `<section class="card analysis-section bank-section"><div class="section-label"><span><span class="section-number">02</span> Взгляд Альфа-Банка</span><span class="pill outline">${bank.status==='available'?'Материалы загружены':'Не подключён'}</span></div>${bank.status==='available'?`<p style="margin-top:18px">${e(bank.summary)}</p>${arr(bank.source_ids).map(id=>`<button class="source-link" data-action="source" data-id="${e(event.id)}" data-source="${e(id)}">${icon('doc',13)} Материал банка</button>`).join('')}`:`<div class="bank-placeholder"><span class="icon-tile">${icon('doc',20)}</span><div><h3>Позиция банка пока недоступна</h3><p>Релевантные аналитические материалы не загружены. Выводы ниже не отражают мнение Альфа-Банка.</p></div></div>`}</section>`;}
  function basis(event,value){if(!value)return '<p class="small muted">Связи с основаниями не переданы.</p>';const factIds=arr(value.fact_ids),featureIds=arr(value.company_feature_refs);return `<div class="small muted" style="margin-top:13px;line-height:1.8"><strong>Основания:</strong>${factIds.map(id=>{const f=event.facts.find(f=>f.id===id);return f?`<p style="font-size:11px;margin:6px 0">${e(f.text)} ${f.has_source?`<button class="source-link" data-action="source" data-id="${e(event.id)}" data-source="${e(f.source_id)}">К источнику ↗</button>`:'(источник отсутствует)'}</p>`:`<p>Факт ${e(id)} не загружен.</p>`;}).join('')}${featureIds.map(ref=>{const f=company().features.find(f=>f.field===ref);return f?`<span class="pill" style="margin:4px 4px 0 0">${e(f.label)}: ${e(M.featureText(f))}</span>`:`<span>Признак ${e(ref)} не загружен.</span>`;}).join('')}</div>`;}
  function risks(event){const ai=event.ai_interpretation;return `<p class="local-note">${state.data?.is_demo?'Возможные последствия из подготовленного демо-разбора. Каждое зависит от указанных условий.':'Возможные последствия из разбора. Каждое зависит от указанных условий.'}</p>${[['risks','Возможные риски','risk','alert'],['opportunities','Возможности','opportunity','trend']].map(([key,label,kind,ico])=>`<h2 style="font-size:19px;margin:22px 0 14px">${label}</h2>${ai[key].length?ai[key].map(item=>`<article class="card risk-card ${kind}"><div class="risk-heading">${icon(ico,15)} ${kind==='risk'?'Условный риск':'Условная возможность'}</div><h3>${e(item.text)}</h3><div class="condition"><strong>При условии:</strong> ${e(item.condition||'Условия не переданы; требуется уточнение.')}</div><details class="disclosure"><summary>На чём основан вывод</summary>${basis(event,item.basis)}</details></article>`).join(''):`<p class="empty-inline">${key==='opportunities'?'Обоснованных возможностей в доступных данных не выявлено. Это не означает, что их нет.':'Риски не описаны в доступном разборе. Это не означает отсутствие риска.'}</p>`}`).join('')}`;}
  function actionCard(event,action,showEvent=false){const done=isDone(event,action);return `<article class="card action-card ${done?'done':''}"><label class="action-title"><input type="checkbox" data-action="toggle-action" data-id="${e(event.id)}" data-action-id="${e(action.id)}" ${done?'checked':''}><h3>${e(action.title)}</h3></label><div class="meta"><span class="pill">${e(action.owner_role||'Ответственный не указан')}</span>${done?'<span class="pill complete">Отмечено выполненным</span>':'<span>Личная отметка</span>'}</div><p>${e(action.reason||'Обоснование не загружено.')}</p>${showEvent?`<a class="source-link" href="${eventUrl(event,'actions')}">${icon('pulse',13)} ${e(event.title)}</a>`:''}<details class="action-checklist"><summary>Что проверить перед действием</summary><ul>${arr(action.check_before_action).map(text=>`<li>${e(text)}</li>`).join('')||'<li>Условия выполнения не переданы. Сверьте исходные данные.</li>'}</ul>${basis(event,action.basis)}</details></article>`;}
  function actionPanel(event){return `<p class="local-note">${state.data?.is_demo?'Предложенные шаги — часть демо-разбора.':'Предложенные шаги собраны по этому разбору.'} Отметки сохраняются ${storageAvailable?'в этом браузере':'только до перезагрузки'}, задачи сотрудникам не отправляются.</p>${event.actions.length?event.actions.map(action=>actionCard(event,action)).join(''):empty('Пока нет обоснованных действий','Сначала нужны исходные данные и проверенный разбор.','tasks','Проверить источники','go-sources')}`;}
  function actionsPage(){const all=events().flatMap(n=>n.actions.map(a=>({event:n,action:a}))),complete=all.filter(x=>isDone(x.event,x.action)).length;return pageHead('План действий','Проверки и следующие шаги из событий вашей компании.','ОТ ИНСАЙТА К ДЕЙСТВИЮ')+`<div class="layout"><div><section class="card" style="margin-bottom:20px"><div class="row spread"><h3 style="margin:0">Ваш прогресс</h3><span class="small muted">${complete} из ${all.length} выполнено</span></div><div class="progress-track" role="progressbar" aria-label="Выполненные шаги" aria-valuemin="0" aria-valuemax="${all.length||1}" aria-valuenow="${complete}"><span style="width:${all.length?complete/all.length*100:0}%"></span></div><p class="local-note" style="margin:0">Личный список в этом браузере. Выполнение отмечается вручную; поручения сотрудникам не отправляются.</p></section>${all.map(x=>actionCard(x.event,x.action,true)).join('')||empty('План пока пуст','Следующие шаги появятся после подготовки обоснованного разбора.','tasks','Открыть события','go-feed')}</div>${contextRail()}</div>`;}
  function sourcesPanel(event){return `<p class="local-note">${state.data?.is_demo?'Тексты ниже — вымышленные первоисточники. Показана связь учебных фактов и выводов; проверка реальных событий не выполнялась.':'Тексты ниже — фрагменты, которые использовал разбор.'}</p>${event.sources.map(source=>`<article class="card source-card"><span class="pill source">${source.is_demo?'Учебный источник':'Внешний источник'}</span><h3>${e(source.title)}</h3><p>${e(source.publisher)} · ${dateLabel(source.date||event.date)}</p><button class="source-link" data-action="source" data-id="${e(event.id)}" data-source="${e(source.id)}">${icon('doc',14)} Читать исходный текст ${icon('external',12)}</button></article>`).join('')||'<p class="empty-inline">Источники не загружены. Сведения о событии пока нельзя проверить.</p>'}<section class="card analysis-section"><h2>Проверка полноты</h2><span class="pill medium">${event.verification?.status==='checked'?'Сверено с источниками':'Нужны дополнительные данные'}</span><ul>${event.missing_data.map(text=>`<li>${e(text)}</li>`).join('')||'<li>Сведения о полноте не переданы.</li>'}</ul>${event.verification.conflicts.length?`<h3>Противоречия</h3><ul>${event.verification.conflicts.map(c=>`<li>${e(typeof c==='string'?c:JSON.stringify(c))}</li>`).join('')}</ul>`:'<p class="small">В фикстуре противоречия не отмечены. Автоматическая проверка не подключена.</p>'}</section><section class="card analysis-section"><h2>Как подготовлен разбор</h2><p style="font-size:11px;margin-bottom:24px">${state.data?.is_demo?'Демонстрация этапов будущего сервиса. Это не журнал выполнения AI-агента.':'Краткий ход разбора. Полный журнал шагов хранится на сервере по trace_id.'}</p>${[['Контекст компании',featureRefs(event).map(f=>f.label).join(', ')||'Релевантные признаки не указаны'],['Отбор события',event.relevance[state.companyId]?.reason||'Основание отбора не загружено.'],['Поиск материалов',`${event.sources.length} ${state.data?.is_demo?'учебных источников. Аналитические материалы банка отсутствуют.':'источников подключено к разбору.'}`],['Интерпретация',event.ai_interpretation.summary?(state.data?.is_demo?'Подготовленный вручную пример со ссылками на данные.':'Вывод со ссылками на факты, профиль и материалы банка.'):'Не подготовлена: исходных данных недостаточно.'],['Проверка и уточнение',event.analysis_status==='ready'?'Проверка источников пройдена.':`Результат неполный. Недостающих сведений: ${event.missing_data.length}.`]].map(([label,text])=>`<div class="trace-step"><div><strong>${e(label)}</strong><p>${e(text)}</p></div></div>`).join('')}</section>`;}
  function questions(event){return `<section class="card question-card"><div class="question-heading">${icon('spark',21)}<h3>Разобраться глубже</h3></div><p class="hint">${state.data?.is_demo?'Задайте вопрос к этому событию.<br>В демо доступны подготовленные ответы.':'Задайте вопрос к этому событию.<br>Ответ собирается по источникам этого разбора.'}</p><span class="pill ai">${state.data?.is_demo?'Демо · без подключения AI':'Ответ готовит сервер'}</span><div class="question-suggestions">${event.suggested_questions.map((q,index)=>`<button data-action="suggest-question" data-id="${e(event.id)}" data-index="${index}">${e(q.question)} ${icon('arrow',12)}</button>`).join('')}</div><form id="question-form" data-id="${e(event.id)}" data-context="${e(questionKey(event))}"><label for="question-input">Ваш вопрос</label><textarea id="question-input" maxlength="1000" placeholder="Что это меняет для моей компании?" required></textarea><button class="button dark" type="submit">${icon('message',15)} Задать вопрос</button></form><div id="question-answer" class="question-answer" role="status" aria-live="polite" hidden></div></section>`;}
  function feedback(event){const key=M.stateKey(state.companyId,event),value=state.feedback[key];return `<div class="feedback"><span>Этот разбор полезен?</span><button data-action="feedback" data-id="${e(event.id)}" data-value="yes" aria-pressed="${value==='yes'}">Да, полезен</button><button data-action="feedback" data-id="${e(event.id)}" data-value="no" aria-pressed="${value==='no'}">Не совсем</button>${value?'<span class="small">Отметка сохранена локально</span>':''}</div>`;}
  function openModal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();}
  function showSource(event,sourceId){const source=event.sources.find(s=>s.id===sourceId);if(!source){toast('Источник не загружен.');return;}const url=M.safeUrl(source.url);openModal('Первоисточник',`<span class="pill source">${source.is_demo?'Вымышленный учебный источник':'Материал источника'}</span><h3 style="margin:17px 0 8px">${e(source.title)}</h3><p>${e(source.publisher)} · ${dateLabel(source.date||event.date)}</p><blockquote>${e(source.text||'Текст источника не загружен.')}</blockquote>${url?`<a class="button secondary" href="${e(url)}" target="_blank" rel="noopener noreferrer">Открыть оригинал ${icon('external',14)}</a>`:`<p class="source-warning">${source.is_demo?'У учебного материала нет внешней ссылки. Он не подтверждает реальное событие.':'Внешняя ссылка не передана. Ниже текст, который использовал разбор.'}</p>`}<p class="small">${event.facts.filter(f=>f.source_id===sourceId).length} факт(а) из этого материала использовано в разборе.</p>`);}
  function showAbout(){openModal('О демонстрации',`<p>Бизнес-пульс показывает путь от события к персональному бизнес-разбору. Компании, новости и источники вымышлены. Интерпретации и ответы подготовлены заранее, генерация AI не выполняется.</p><p><strong>Позиция Альфа-Банка не представлена:</strong> аналитические материалы не подключены. Реальные сбор новостей, ранжирование моделью и проверка фактов требуют сервера.</p><p>Сохранённые события, отметки действий и обратная связь хранятся ${storageAvailable?'локально в этом браузере':'в памяти до перезагрузки: хранилище браузера недоступно'}. Данные никуда не отправляются в автономном режиме.</p><label for="demo-state">Проверить состояние интерфейса</label><select id="demo-state">${[['ready','Обычная демонстрация'],['loading','Загрузка'],['empty','Нет событий'],['error','Ошибка загрузки'],['partial','Не хватает данных']].map(([key,label])=>`<option value="${key}" ${state.scenario===key?'selected':''}>${label}</option>`).join('')}</select><button class="button primary" data-action="apply-scenario">Показать состояние</button>`);}
  function resetFilters(){state.query='';state.category='all';state.priority='all';state.period='all';state.sort='relevance';}
  function refreshFocus(button){const action=button.dataset.action,id=button.dataset.id,actionId=button.dataset.actionId;const top=window.scrollY;render();const match=[...document.querySelectorAll('[data-action]')].find(b=>b.dataset.action===action&&b.dataset.id===id&&(!actionId||b.dataset.actionId===actionId));match?.focus({preventScroll:true});window.scrollTo({top,behavior:'instant'});}
  function switchTab(key,focusTab=true){const r=route();answerRequest++;history.replaceState(null,'',`#insight/${encodeURIComponent(decodeURIComponent(r.id))}/${key}`);render();if(focusTab){const selected=$(`#tab-${key}`);selected?.focus({preventScroll:true});selected?.scrollIntoView?.({block:'nearest',inline:'nearest'});}}
  async function askQuestion(question,event){
    if(!$('#question-answer'))return;
    const key=questionKey(event),request=++answerRequest,session={draft:question,pending:true,html:'',error:false,request};
    const companyId=state.companyId,role=state.role;
    questionSessions.set(key,session);restoreQuestion();
    try{let result;const base=String(window.ALFA_CONFIG.apiBaseUrl||'').replace(/\/$/,'');
      if(base){result=await jsonRequest(`${base}/insights/${encodeURIComponent(event.id)}/questions`,{method:'POST',question:true,body:JSON.stringify({company_id:companyId,role,question})});if(typeof result?.answer!=='string'||typeof result.is_demo!=='boolean'||!Array.isArray(result.source_ids))throw new Error('Ответ не содержит обязательных данных о происхождении.');}
      else{await new Promise(resolve=>setTimeout(resolve,400));const prepared=event.suggested_questions.find(q=>q.question.trim().toLowerCase()===question.trim().toLowerCase());result=prepared?{answer:prepared.answer,is_demo:true,source_ids:event.sources.map(s=>s.id)}:{answer:'Для этого вопроса нет подготовленного ответа. AI-сервис не подключён, поэтому новый вывод не сформирован. Используйте примеры вопросов выше или проверьте исходные материалы.',is_demo:true,source_ids:[]};}
      if(questionSessions.get(key)?.request!==request)return;
      session.html=`<strong>${result.is_demo?'ПОДГОТОВЛЕННЫЙ ДЕМО-ОТВЕТ':'AI-ИНТЕРПРЕТАЦИЯ · ОТВЕТ СЕРВЕРА'}</strong>${e(result.answer)}${result.source_ids.length?`<div style="margin-top:13px">${result.source_ids.map(id=>event.sources.some(s=>s.id===id)?`<button class="source-link" data-action="source" data-id="${e(event.id)}" data-source="${e(id)}">${icon('doc',13)} Посмотреть основание</button>`:`<span class="small">Источник ${e(id)} не загружен.</span>`).join('<br>')}</div>`:''}`;
    }catch(error){if(questionSessions.get(key)?.request!==request)return;session.error=true;session.html=e(`Не удалось получить ответ. ${error.message} Вопрос сохранён в поле — попробуйте отправить снова.`);}
    finally{if(questionSessions.get(key)?.request===request){session.pending=false;if($('#question-form')?.dataset.context===key)restoreQuestion();}}
  }
  document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;let item;if(button.dataset.id)item=events().find(n=>n.id===button.dataset.id);
    if(action==='close-modal')$('#modal').close();
    else if(action==='reload'){if(state.scenario==='error')state.scenario='ready';load();}
    else if(action==='restore'){state.scenario='ready';load();}
    else if(action==='about')showAbout();
    else if(action==='apply-scenario'){state.scenario=$('#demo-state').value;$('#modal').close();resetFilters();if(state.scenario==='partial')location.hash='#insight/event_demo_001/analysis';load();}
    else if(action==='go-feed')location.hash='#feed';
    else if(action==='go-sources')switchTab('sources');
    else if(action==='reset-filters'){resetFilters();render();$('#search')?.focus();}
    else if(action==='ranking')openModal('Почему эти события',`<p>События отобраны по признакам компании: отрасль, кредитные продукты, импорт, контрагенты. Для роли «${e(M.roles[state.role])}» используется отдельная оценка значимости.</p><p>В этом демо связи, оценки и интерпретации заданы вручную. Смена компании меняет набор событий; смена роли меняет порядок и акцент разбора.</p><p>В рабочем сервисе этот отбор должен выполнять сервер с проверкой фактов, доступов и аналитических материалов банка.</p>`);
    else if(action==='bookmark'&&item){const list=saved(),adding=!list.includes(item.id);state.bookmarks[state.companyId]=adding?[...list,item.id]:list.filter(id=>id!==item.id);persist();refreshFocus(button);toast(adding?'Событие сохранено в вашей подборке.':'Событие убрано из сохранённого.');}
    else if(action==='source'&&item)showSource(item,button.dataset.source);
    else if(action==='suggest-question'&&item){const q=item.suggested_questions[Number(button.dataset.index)];if(q){$('#question-input').value=q.question;askQuestion(q.question,item);}}
    else if(action==='feedback'&&item){state.feedback[M.stateKey(state.companyId,item)]=button.dataset.value;persist();refreshFocus(button);toast('Спасибо. Отметка сохранена локально.');}
  });
  document.addEventListener('change',event=>{const target=event.target;if(target.id==='company-select'){state.companyId=target.value;resetFilters();persist();answerRequest++;if(route().view==='insight')location.hash='#feed';if(window.ALFA_CONFIG.apiBaseUrl)load();else render(true);}
    else if(target.id==='role-select'){state.role=target.value;persist();answerRequest++;if(window.ALFA_CONFIG.apiBaseUrl)load();else render();toast('Приоритеты и акцент разбора обновлены для вашей роли.');}
    else if(['category-filter','priority-filter','period-filter','sort-select'].includes(target.id)){state[{'category-filter':'category','priority-filter':'priority','period-filter':'period','sort-select':'sort'}[target.id]]=target.value;$('#feed-results').innerHTML=feedResults(route().view==='saved');}
    else if(target.dataset.action==='toggle-action'){const item=events().find(n=>n.id===target.dataset.id),a=item?.actions.find(a=>a.id===target.dataset.actionId);if(a){const key=doneKey(item,a);state.done=target.checked?[...new Set([...state.done,key])]:state.done.filter(k=>k!==key);persist();refreshFocus(target);toast(target.checked?'Шаг отмечен выполненным в личном плане.':'Отметка выполнения снята.');}}});
  document.addEventListener('input',event=>{if(event.target.id==='search'){state.query=event.target.value;$('#feed-results').innerHTML=feedResults(route().view==='saved');}});
  document.addEventListener('submit',event=>{if(event.target.id==='question-form'){event.preventDefault();const item=events().find(n=>n.id===event.target.dataset.id),question=$('#question-input').value.trim();if(question&&item)askQuestion(question,item);}});
  document.addEventListener('click',event=>{if(event.target.closest('.skip-link')){event.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}const tab=event.target.closest('[data-tab]');if(tab)switchTab(tab.dataset.tab);});
  document.addEventListener('keydown',event=>{const tab=event.target.closest('[data-tab]');if(!tab)return;const keys=Object.keys(tabLabels),index=keys.indexOf(tab.dataset.tab);let target;if(event.key==='ArrowRight')target=keys[(index+1)%keys.length];if(event.key==='ArrowLeft')target=keys[(index+keys.length-1)%keys.length];if(event.key==='Home')target=keys[0];if(event.key==='End')target=keys.at(-1);if(target){event.preventDefault();switchTab(target);}});
  $('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
  window.addEventListener('hashchange',()=>{answerRequest++;render(true);});
  load();
})();
